def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    arm_patches = image_patch.find("arm")
    if not arm_patches: 
        return image_patch

    # Sort arms based on their vertical center
    arm_patches.sort(key=lambda p: p.vertical_center)

    # Find the pair of arms that are closest vertically
    min_distance = float('inf')
    closest_pair = None
    for i in range(len(arm_patches)):
        for j in range(i + 1, len(arm_patches)):
            dist = abs(arm_patches[i].vertical_center - arm_patches[j].vertical_center)
            if dist < min_distance:
                min_distance = dist
                closest_pair = (arm_patches[i], arm_patches[j])

    # Check if the arms are crossed
    if closest_pair[0].horizontal_center < closest_pair[1].horizontal_center:
        return closest_pair[0]
    else:
        return closest_pair[1]

