def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    boy_patches = image_patch.find("boy")
    glasses_patches = image_patch.find("glasses")

    if not boy_patches or not glasses_patches:
        return image_patch

    boy_with_glasses = []
    for boy in boy_patches:
        for glasses in glasses_patches:
            if boy.overlaps_with(glasses.left, glasses.lower, glasses.right, glasses.upper):
                boy_with_glasses.append(boy)
                break

    return boy_with_glasses[0] if boy_with_glasses else image_patch

