def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    shirts = image_patch.find("shirt")
    shorts = image_patch.find("shorts")

    blue_shirts = [s for s in shirts if s.verify_property("shirt", "blue")]
    tan_shorts = [t for t in shorts if t.verify_property("shorts", "tan")]

    if not blue_shirts or not tan_shorts:
        return image_patch

    blue_shirt = blue_shirts[0]
    tan_short = tan_shorts[0]

    if is_between_3d(blue_shirt, tan_short, blue_shirt):
        return blue_shirt
    elif is_between_3d(tan_short, blue_shirt, tan_short):
        return tan_short
    else:
        return blue_shirt if blue_shirt.horizontal_center < tan_short.horizontal_center else tan_short
